; Walk-in at the start of a bout
; $8358-$83a8

; At the start of a bout, walks both fighters in until the distance is less than 6. Then the bout starts.
update_walk_in
        lda setup_active
        ora final_stage
        bmi update_walk_in_done
        lda walk_in_active
        bpl update_walk_in_done
        lda fighter_distance
        cmp #$06
        bcc update_walk_in_end
        jsr add_time_bonus
        ldx #$01
update_walk_in_loop
        lda #$81                        ; Move $01: walks forward.
        cmp fighter_move,x
        beq update_walk_in_next
        sta fighter_move,x
        lda #$00
        sta fighter_move_step,x
        jsr reset_timer                 ; Sets the time to 60 seconds.
update_walk_in_next
        dex
        bpl update_walk_in_loop
        lda sound_request
        ora voice_tune
        bmi update_walk_in_done
        lda #$89                        ; Starts the sound effects $89-$8b of the walk-in.
        sta sound_request
        lda #$8a
        sta sound_request+1
        lda #$8b
        sta sound_request+2
        rts
update_walk_in_end
        lda #$00
        sta walk_in_active
        lda #$ff
        sta fighter_idle_timer          ; Starts the idle timers of both fighters.
        sta fighter_idle_timer+1
        lda sound_off
        bmi update_walk_in_done
        jsr stop_sound                  ; In sound effects mode, waits for the volume and starts the fade-in again.
        lda #$81
        sta fade_in_request
update_walk_in_done
        rts
